387	     * trim, collapse internal runs of whitespace to a single space and lower-case.
388	     */
389	    private static String normalize(String value) {
390	        if (value == null) {
391	            return "";
392	        }
393	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
394	    }
