public Owner toOwner(OwnerFieldsDto ownerDto) {
    if ( ownerDto == null ) {
        return null;
    }

    Owner owner = new Owner();

    owner.setFirstName( ownerDto.getFirstName() );
    owner.setLastName( ownerDto.getLastName() );
    owner.setAddress( ownerDto.getAddress() );
    owner.setCity( ownerDto.getCity() );
    owner.setTelephone( ownerDto.getTelephone() );
    owner.setEmail( ownerDto.getEmail() );
    owner.setPostcode( ownerDto.getPostcode() );
    owner.setRegistrationDate( ownerDto.getRegistrationDate() );
    owner.setBirthDate( ownerDto.getBirthDate() );

    return owner;
}

